<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class FootballMatch extends Model { protected $table='matches'; protected $guarded=[]; protected $casts=['kickoff_at'=>'datetime','venue_latitude'=>'float','venue_longitude'=>'float','conflict_details'=>'array']; public function getIsLiveWindowAttribute(): bool { return $this->kickoff_at && !in_array($this->status,['finished','cancelled','postponed'],true) && $this->kickoff_at->lte(now()) && $this->kickoff_at->copy()->addHours(2)->gt(now()); } public function league(){return $this->belongsTo(League::class);} public function homeTeam(){return $this->belongsTo(Team::class,'home_team_id');} public function awayTeam(){return $this->belongsTo(Team::class,'away_team_id');} public function recommendations(){return $this->hasMany(Recommendation::class,'match_id');} public function odds(){return $this->hasMany(Odd::class,'match_id');} public function providerMappings(){return $this->hasMany(ProviderMatchMapping::class,'match_id');} public function weatherSnapshots(){return $this->hasMany(MatchWeatherSnapshot::class,'match_id');} public function latestWeatherSnapshot(){return $this->hasOne(MatchWeatherSnapshot::class,'match_id')->latestOfMany('fetched_at');} public function actualResult(): \Illuminate\Database\Eloquent\Relations\HasOne { return $this->hasOne(GameActualResult::class, 'game_id'); }
public function betlensPredictions(): \Illuminate\Database\Eloquent\Relations\HasMany { return $this->hasMany(BetlensPrediction::class, 'game_id'); }
public function externalPlatformPredictions(): \Illuminate\Database\Eloquent\Relations\HasMany { return $this->hasMany(ExternalPlatformPrediction::class, 'game_id'); }
}
